def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'D'

    # Cooperative opening to encourage mutual cooperation.
    if n < 3:
        return 'C'

    opp = [h[1] for h in history]
    my = [h[0] for h in history]
    last_my = my[-1]
    last_opp = opp[-1]

    # Count opponent cooperation and defection in recent windows.
    r10 = opp[-10:] if n >= 10 else opp
    r5 = opp[-5:] if n >= 5 else opp
    d10 = r10.count('D')
    d5 = r5.count('D')
    total_d = opp.count('D')
    opp_c_rate = (n - total_d) / n

    # Very cooperative opponent: mostly cooperate, exploit sparingly near end.
    if total_d == 0:
        if n >= 95:
            return 'D'
        if n == 50:
            return 'D'
        return 'C'

    # Near the end, exploit a very cooperative opponent.
    if n >= 95:
        if opp_c_rate > 0.8:
            return 'D'
        if d5 >= 2:
            return 'D'
        return 'C'

    # Opponent appears mostly cooperative: only punish clear defection runs.
    if opp_c_rate > 0.85 and d10 <= 1:
        if last_opp == 'D':
            return 'D'
        if n % 13 == 0:
            return 'D'
        return 'C'

    # Hard punishment for opponents who defect heavily.
    if d10 >= 6 or d5 >= 4:
        return 'D'

    # If opponent just defected, retaliate but allow occasional forgiveness.
    if last_opp == 'D':
        if d5 >= 3:
            return 'D'
        if last_my == 'D':
            # Defection spiral: try to restore cooperation sometimes.
            if rng.random() < 0.15:
                return 'C'
            return 'D'
        # Single defection: retaliate, but forgive sometimes.
        if rng.random() < 0.08 and n < 90:
            return 'C'
        return 'D'

    # Opponent cooperated. If we defected last round, return to cooperation.
    if last_my == 'D':
        if d5 >= 3:
            return 'D'
        return 'C'

    # Both cooperated: cooperate, with rare probing of soft opponents.
    if d10 == 0 and n > 15 and n < 85:
        if n % 17 == 0 and rng.random() < 0.2:
            return 'D'
    return 'C'
